from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.resources.expectations.utils import x2ap_message, INITIATING_MESSAGE, SUCCESSFUL_OUTCOME, UNSUCCESSFUL_OUTCOME
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageHeader
from taf.ul.ettf.msg_capture.expectation_builders import Unexpected


class x2ap_messages(ExpectationsManager):
    def expect_sgnb_addition_request(self):
        self.append_expectation(MessageHeader(*x2ap_message('SgNBAdditionRequest', INITIATING_MESSAGE)))

    def expect_sgnb_addition_request_reject(self):
        self.append_expectation(MessageHeader(*x2ap_message('SgNBAdditionRequestReject', UNSUCCESSFUL_OUTCOME)))

    def expect_sgnb_addition_request_acknowledge(self):
        self.append_expectation(MessageHeader(*x2ap_message('SgNBAdditionRequestAcknowledge', SUCCESSFUL_OUTCOME)))

    def expect_sgnb_reconfiguration_complete(self):
        self.append_expectation(MessageHeader(*x2ap_message('SgNBReconfigurationComplete', INITIATING_MESSAGE)))

    def expect_x2_ue_context_release(self):
        self.append_expectation(MessageHeader(*x2ap_message('UEContextRelease', INITIATING_MESSAGE)))

    def expect_x2_handover_request(self):
        self.append_expectation(MessageHeader(*x2ap_message('HandoverRequest', INITIATING_MESSAGE)))

    def expect_x2_handover_request_acknowledge(self):
        self.append_expectation(MessageHeader(*x2ap_message('HandoverRequestAcknowledge', SUCCESSFUL_OUTCOME)))

    def expect_no_sgnb_addition_request(self):
        self.append_expectation(MessageHeader(*x2ap_message('SgNBAdditionRequest', INITIATING_MESSAGE), policy=Unexpected))

    def expect_no_sgnb_addition_request_reject(self):
        self.append_expectation(MessageHeader(*x2ap_message('SgNBAdditionRequestReject', UNSUCCESSFUL_OUTCOME), policy=Unexpected))

    def expect_no_sgnb_addition_request_acknowledge(self):
        self.append_expectation(MessageHeader(*x2ap_message('SgNBAdditionRequestAcknowledge', SUCCESSFUL_OUTCOME), policy=Unexpected))
